import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync,existsSync}from'node:fs';import vm from'node:vm';import{systemMapData}from'../scripts/system-map-20261012.mjs';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');const data=JSON.parse(read('worlds/liminal-doors-register-20261016.json'));
test('complete unique floor roster preserves latest owner requirements',()=>{assert.equal(data.scenes.length,37);assert.equal(new Set(data.scenes.map(s=>s.animal)).size,37);assert.equal(new Set(data.scenes.map(s=>s.number)).size,37);assert.equal(data.scenes.filter(s=>s.tags.includes('aero')).length,4);assert.match(data.scenes.find(s=>s.animal==='Chipmunk').feature,/deformation/);assert.match(data.constraints.join(' '),/actual return/);assert.match(data.constraints.join(' '),/spiral staircase/);assert.equal(data.platform,'PC');});
test('both generated pages parse and link to each other, with one L3 bubble on caretaker',()=>{for(const f of ['apps/the-threshold-20261016.html','apps/liminal-doors-20261016.html']){const html=read(f);assert.ok(!html.includes('__DATA__'));for(const [,attrs,body]of html.matchAll(/<script([^>]*)>([\s\S]*?)<\/script>/g)){if(attrs.includes('application/json'))JSON.parse(body);else new vm.Script(body);}assert.ok(html.includes('liminal-doors-20261016.html'));if(f.includes('liminal-doors-20261016'))assert.ok(html.includes('the-threshold-20261016.html'));}const html=read('apps/the-threshold-20261016.html');assert.equal(html.match(/<!--astra-l3-start-->/g).length,1);assert.ok(html.includes('Clicker Training'));assert.ok(html.includes('No L3 account'));});
test('registered hub pages all embed activity',()=>{const r=JSON.parse(read('pets.json'));for(const p of r.pets){const html=read(p.interface_local_url);assert.ok(html.includes('data-astra-l3-config'),p.repo);}});
test('caretaker catalog route is navigation, not animal enrollment',()=>{const r=JSON.parse(read('pets.json')),c=JSON.parse(read('pet-programs.json')),map=systemMapData(r,JSON.parse(read('system-map.json')),c);const n=map.nodes.find(n=>n.name==='Door Dormouse');assert.equal(n.programUrl,'apps/the-threshold-20261016.html');assert.ok(![...r.pets,...r.pipeline].some(p=>p.repo==='the-threshold'));assert.equal(c.programs.find(p=>p.number===42).program,"Nessi's Ocean");const invalid=structuredClone(c);invalid.programs.find(p=>p.icon==='Door Dormouse').interface_local_url='javascript:alert(1)';assert.equal(systemMapData(r,JSON.parse(read('system-map.json')),invalid).nodes.find(n=>n.name==='Door Dormouse').programUrl,undefined);});
